from itertools import permutations
from pwn import remote

# Example checksum function simulated as found in the analysis
def checksum_simulation(input_string):
    total = 0
    for char in input_string:
        total += ord(char)  # Simplistic sum based on ASCII values (adjust based on actual logic)
    return total

def find_valid_input(target_checksum, length):
    charset = 'abcdefghijklmnopqrstuvwxyz_'  # Character set to try
    for candidate in permutations(charset, length):
        if checksum_simulation(candidate) == target_checksum:
            return ''.join(candidate)
    return None

# Connect to the remote server
io = remote('rev.chal.csaw.io', 8000)

def main():
    target_checksum = 505  # Target checksum (0x1f9)
    valid_input = find_valid_input(target_checksum, length=5)  # Assuming input length = 5 for testing

    if valid_input:
        print("Valid Input Found:", valid_input)
        io.sendline(valid_input)
        response = io.recvall()
        print(response.decode())
    else:
        print("No valid input found")

if __name__ == "__main__":
    main()

